def find_mode(numbers):
    most_freq = 0
    mode = None

    counts = {}
    for num in numbers:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    for num in counts:
        if counts[num] > most_freq:
            most_freq = counts[num]
            mode = num

    return mode

