def insertionSort(array):
    """Algorithm to sort an array using insertion sort."""
    for j in range(1,len(array)):
        key = array[j]
        i = j-1
        while i >= 0 and array[i]> key:
            array[i+1] = array[i]
            i-=1
        array[i+1] = key

