def longestZeroSeq(inputStr):
    maxLength = 0 

    currentLength = 0

    for c in inputStr:
        if c == '0':
            currentLength += 1
        else:
            maxLength = max(maxLength, currentLength) 
            currentLength = 0

    maxLength = max(maxLength, currentLength)

    return maxLength

