def generate_primes(max): 
    primes_list = [2] 
    for i in range(3, max + 1): 
        curr = True 
        for p in primes_list: 
            if i % p == 0: 
                curr = False 
        if curr: 
            primes_list.append(i) 
    return primes_list

def binary_search(arr, target):
  low = 0
  high = len(arr) - 1

  while low <= high:
    mid = (low + high) // 2 # floor division
    guess = arr[mid]

    if guess == target:
      return mid
    elif guess > target:
      high = mid - 1
    else:
      low = mid + 1
  return None

