class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def length(self):
        return (self.x**2 + self.y**2)**(1/2)

    def add(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def subtract(self, other):
        return Vector(self.x - other.x, self.y - other.y)

def is_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False

    s1_dict = dict()
    for i, char in enumerate(s1):
        if char in s1_dict:
            if s1_dict[char] != s2[i]:
                return False
        else:
            s1_dict[char] = s2[i]

    return True

class Vector3D: 
    def __init__(self, x, y, z): 
        self.x = x 
        self.y = y 
        self.z = z 

    def magnitude(self): 
        return (self.x**2 + self.y**2 + self.z**2)**0.5 

    def normalize(self): 
        magnitude = self.magnitude() 
        self.x /= magnitude 
        self.y /= magnitude 
        self.z /= magnitude

